  // src/lib/hast.ts
  function hastToHtml(node2) {
    if (node2.type === "text") return node2.value ?? "";
    if (node2.type === "root") {
      return (node2.children ?? []).map(hastToHtml).join("");
    }
    if (node2.type !== "element" || !node2.tagName) return "";
    const props = Object.entries(node2.properties ?? {}).map(([k, v2]) => {
      if (v2 == null || v2 === false) return "";
      const name2 = k === "className" ? "class" : k;
      const value = Array.isArray(v2) ? v2.join(" ") : String(v2);
      if (value === "") return "";
      return ` ${name2}="${value.replace(/"/g, "&quot;")}"`;
    }).join("");
    const children = (node2.children ?? []).map(hastToHtml).join("");
    return `<${node2.tagName}${props}>${children}</${node2.tagName}>`;
  }

